#include <iostream>
#include <sstream>

int main() {
    // Demonstrate stream routing using simulated buffered and unbuffered destinations
    std::ostringstream normalOut;
    std::ostringstream errorOut;
    std::ostringstream logOut;

    // Insertion via stream insertion operator (<<)
    normalOut << "Standard output message\n";
    errorOut << "Unbuffered error message\n";
    logOut << "Buffered log event\n";

    std::cout << "Routing summary:\n"
              << "[cout]: " << normalOut.str()
              << "[cerr]: " << errorOut.str()
              << "[clog]: " << logOut.str();

    return 0;
}

#include <iostream>

int main() {
    const char* const phrase = "C++ Streams";

    // 1. Output as string content
    std::cout << "String content: " << phrase << "\n";

    // 2. Output memory address via static_cast<const void*>
    const void* address = static_cast<const void*>(phrase);
    std::cout << "Pointer address is non-null: " << (address != nullptr ? "true" : "false") << "\n";

    // 3. Cascading calls to put()
    std::cout << "Output via put(): ";
    std::cout.put('O').put('K').put('\n');

    return 0;
}

#include <iostream>
#include <sstream>

int main() {
    // Simulate input stream containing characters and whitespace
    std::string testData = "A B\n";
    std::istringstream stream(testData);

    std::cout << "Initial eof state: " << stream.eof() << "\n";

    int ch;
    std::cout << "Characters read: ";
    while ((ch = stream.get()) != EOF) {
        std::cout.put(static_cast<char>(ch));
    }

    std::cout << "Final eof state: " << stream.eof() << "\n";
    return 0;
}
